insert into public.mastery_bank (chapter, term, def) values
(1,'Health','A combination of physical, mental/emotional, and social well-being — not just the absence of disease.'),
(1,'Wellness','The quality of life that results from taking positive steps toward achieving your full health potential.'),
(1,'Health Triangle','A model showing the three sides of health: physical, mental/emotional, and social — all must be balanced.'),
(1,'Lifestyle factors','Personal behaviors and habits that affect your long-term health, both positively and negatively.'),
(1,'Health literacy','The ability to find, understand, evaluate, and apply health information to make responsible decisions.'),
(1,'Heredity','The passing of traits from biological parents to their children through genes.'),
(1,'Environment','All living and nonliving things around you, including your community, culture, and physical surroundings.'),
(1,'Culture','The beliefs, values, and practices shared by a group of people — a major influence on health decisions.'),
(1,'Peers','People of the same age who share similar interests; a powerful influence on teen health behavior.'),
(1,'Risk behaviors','Actions or habits that increase the likelihood of negative outcomes to one''s health or others.'),
(1,'Prevention','Taking action to avoid disease, injury, and other health problems before they occur.'),
(1,'Abstinence','The deliberate decision to refrain from a risky behavior.'),
(1,'Health promotion','The process of enabling people to increase control over and improve their health.'),
(1,'Protective factors','Conditions or attributes that reduce the impact of risk factors on health outcomes.'),
(1,'Attitude','A feeling or disposition toward a person, object, or idea that influences behavior.'),
(2,'Goal setting','The process of identifying something you want to accomplish and creating a plan to achieve it.'),
(2,'SMART goals','Goals that are Specific, Measurable, Achievable, Realistic, and Time-bound.'),
(2,'Decision making','A five-step process for making healthy, responsible choices.'),
(2,'Values','The beliefs and principles that guide your behavior and decisions.'),
(2,'Refusal skills','Strategies that help you say no to things that are harmful or illegal.'),
(2,'Conflict resolution','A process for resolving disagreements in a peaceful, constructive way.'),
(2,'Stress management','Techniques for controlling and reducing the physical and emotional effects of stress.'),
(2,'Communication skills','The ability to share information clearly with others using listening, speaking, and body language.'),
(2,'Self-management','The ability to control your emotions, behaviors, and actions to make healthy choices.'),
(2,'Advocacy','Taking action to promote health and influence others to make positive choices.'),
(2,'Accessing information','The skill of finding and evaluating reliable, accurate health information from valid sources.'),
(2,'Analyzing influences','The ability to identify and examine the factors that affect health beliefs and behaviors.'),
(3,'Mental health','The state of your psychological and emotional well-being — how you think, feel, and cope with life.'),
(3,'Emotions','Signals that tell your mind and body how to react to situations.'),
(3,'Self-concept','The view you have of yourself — your strengths, weaknesses, thoughts, and feelings.'),
(3,'Self-esteem','The confidence and satisfaction you have in yourself and your own abilities.'),
(3,'Empathy','The ability to understand and share the feelings of another person.'),
(3,'Emotional intelligence','The ability to recognize, understand, and manage your own emotions and recognize emotions in others.'),
(3,'Resiliency','The ability to recover from setbacks, adapt to change, and keep going in the face of adversity.'),
(3,'Grief','The emotional response to loss — a normal and necessary process that takes time.'),
(3,'Coping strategies','Healthy ways of managing and reducing the emotional pain of difficult situations.'),
(3,'Defense mechanisms','Unconscious mental strategies used to protect yourself from uncomfortable emotions.'),
(3,'Positive affirmations','Statements that remind you of your strengths and help reinforce a positive self-image.'),
(3,'Mindfulness','The practice of focusing attention on the present moment with openness and without judgment.'),
(4,'Stress','The body''s and mind''s reaction to everyday demands and threats, real or perceived.'),
(4,'Stressor','Any situation, event, or person that causes stress.'),
(4,'Fight-or-flight response','The body''s automatic physiological reaction to a perceived threat — prepares to fight or flee.'),
(4,'Adrenaline','The hormone released during stress that increases heart rate, blood pressure, and energy.'),
(4,'Eustress','Positive stress that motivates and energizes, such as excitement before a sports event.'),
(4,'Distress','Negative stress that feels overwhelming and harmful to health.'),
(4,'Chronic stress','Ongoing, long-term stress that persists over weeks or months and damages health.'),
(4,'Relaxation response','The body''s ability to slow down and recover after a stressful event.'),
(4,'Time management','The practice of organizing and prioritizing tasks to reduce stress and increase productivity.'),
(4,'Support network','Friends, family, and others who provide emotional encouragement and practical help.'),
(4,'Burnout','A state of physical and emotional exhaustion from prolonged, unmanaged stress.'),
(4,'Cortisol','The primary stress hormone; sustained high levels damage the immune system and cardiovascular health.'),
(5,'Mental disorder','An illness that affects a person''s thinking, feeling, or behavior significantly enough to cause distress.'),
(5,'Anxiety disorder','A category of mental health conditions characterized by excessive, persistent fear or worry.'),
(5,'Depression','A mood disorder marked by persistent sadness, hopelessness, loss of interest, and low energy.'),
(5,'Suicide','The act of intentionally ending one''s own life — a preventable public health crisis.'),
(5,'Suicide prevention','Strategies and actions to recognize warning signs and connect people to help before a crisis.'),
(5,'Eating disorder','A serious mental illness involving extreme disturbances in eating behavior and body image.'),
(5,'Anorexia nervosa','An eating disorder involving severe restriction of food intake driven by fear of weight gain.'),
(5,'Bulimia nervosa','An eating disorder involving cycles of binge eating followed by purging behaviors.'),
(5,'PTSD','Post-Traumatic Stress Disorder — a mental health condition triggered by experiencing or witnessing trauma.'),
(5,'Therapy','Treatment by a trained mental health professional using evidence-based psychological methods.'),
(5,'Psychiatry','A branch of medicine focused on diagnosing, treating, and preventing mental disorders.'),
(5,'Stigma','Negative attitudes or discrimination against people with mental health conditions — a major barrier to seeking help.'),
(6,'Relationship','A bond or connection between people based on shared experiences, trust, and mutual care.'),
(6,'Communication','The process of sharing information, thoughts, and feelings using verbal and nonverbal methods.'),
(6,'Active listening','Fully concentrating on what someone is saying, showing you understand, and responding thoughtfully.'),
(6,'Assertiveness','The ability to express your thoughts and feelings confidently and respectfully, without aggression.'),
(6,'Boundary','A limit you set to protect your physical, emotional, and mental well-being in relationships.'),
(6,'Trust','The firm belief in the reliability, truth, or ability of another person — the foundation of healthy relationships.'),
(6,'Respect','Treating others with consideration for their feelings, rights, and boundaries.'),
(6,'Reciprocity','The mutual exchange of benefits, care, or support between people in a healthy relationship.'),
(6,'Jealousy','A feeling of insecurity or fear of losing something or someone to another — can damage relationships.'),
(6,'Healthy relationship','A relationship built on trust, respect, communication, equality, and support for each other''s goals.'),
(7,'Siblings','Brothers and sisters.'),
(7,'Nuclear family','Two parents and one or more children living in the same home.'),
(7,'Blended family','A family formed when a single parent remarries, bringing together children from previous relationships.'),
(7,'Extended family','A family that includes relatives beyond parents and children, such as grandparents, aunts, uncles and cousins.'),
(7,'Foster care','The temporary placement of children in the homes of adults who are not related to them.'),
(7,'Affirmation','Positive feedback that helps others feel appreciated and supported.'),
(7,'Separation','A decision by two married people to live apart from each other.'),
(7,'Divorce','A legal end to a marriage contract.'),
(7,'Custody','The legal right to make decisions affecting children and the responsibility for their care.'),
(7,'Abuse','The physical, mental, emotional, or sexual mistreatment of one person by another.'),
(7,'Domestic violence','Acts of violence or abuse involving family members.'),
(7,'Spousal abuse','Domestic violence or abuse directed at a spouse or partner.'),
(7,'Child abuse','Domestic abuse directed at a child, including physical, emotional, or sexual harm.'),
(7,'Neglect','The failure to provide for a child''s basic needs.'),
(7,'Elder abuse','The abuse or neglect of older family members.'),
(7,'Cycle of violence','The pattern of repeating violent or abusive behaviors from one generation to the next.'),
(7,'Crisis center','A facility that offers advice and support to people dealing with personal emergencies.'),
(8,'Peers','People your age who share similar interests.'),
(8,'Platonic friendship','A friendship with someone of a different gender involving genuine affection, but without romantic involvement.'),
(8,'Clique','A small circle of friends who exclude people viewed as outsiders.'),
(8,'Peer pressure','The influence that people your age may have on your actions and behaviors.'),
(8,'Harassment','Persistently annoying or targeting others through hurtful behaviors like name-calling, teasing, or bullying.'),
(8,'Manipulation','An indirect, dishonest way to control or influence other people.'),
(8,'Refusal skills','Communication strategies that help you say no when urged to take part in unsafe or unhealthy behaviors.'),
(8,'Priorities','The goals, tasks, values, and activities you judge to be most important.'),
(8,'Intimacy','A closeness between two people that develops over time through genuine connection and trust.'),
(8,'Infatuation','Exaggerated feelings of intense passion that can feel overwhelming but are often short-lived.'),
(8,'Abstinence','A deliberate decision to avoid high-risk behaviors, including sexual activity and the use of alcohol, tobacco, and other drugs.'),
(8,'Self-control','The ability to use responsibility and values to override emotions in the moment.'),
(8,'Sexually transmitted infections (STIs)','Infectious diseases spread from person to person through sexual contact.'),
(9,'Conflict','Any disagreement, struggle, or fight.'),
