(9,'Confidentiality','Respecting the privacy of both parties and keeping details of a discussion secret.'),
(9,'Peer mediation','A process in which specially trained students help other students resolve conflicts peacefully.'),
(9,'Violence','The threatened or actual use of physical force or power to harm another person or damage property.'),
(9,'Assault','An unlawful physical attack or threat of attack.'),
(9,'Random violence','Violence committed for no particular reason against an unrelated victim.'),
(9,'Homicide','The willful killing of one human being by another.'),
(9,'Sexual violence','Any form of unwelcome sexual contact directed at an individual.'),
(9,'Bullying','Repeated, deliberate hurtful behavior by someone who has more power than the target.'),
(9,'Cyberbullying','Bullying that happens through phones, social media, games, or other technology.'),
(9,'Physical abuse','A pattern of intentionally causing bodily harm or injury to another person.'),
(9,'Emotional abuse','A pattern of attacking another person''s emotional development and sense of worth.'),
(9,'Verbal abuse','The use of words to mistreat or injure another person; a form of emotional abuse.'),
(9,'Stalking','Repeatedly following, harassing, or threatening an individual in person or online.'),
(10,'Nutrients','Substances in food that provide energy and materials the body needs to grow, repair, and function.'),
(10,'Carbohydrates','The body''s primary energy source; should make up 45–65% of daily calories.'),
(10,'Proteins','Nutrients that build and repair cells, muscles, and tissues; made of amino acids.'),
(10,'Fats','Nutrients that store energy, protect organs, and support vitamin absorption; essential in moderation.'),
(10,'Vitamins','Organic compounds needed in small amounts to regulate body functions and prevent disease.'),
(10,'Minerals','Inorganic substances (calcium, iron, zinc) essential for bone health, blood, and body functions.'),
(10,'MyPlate','The USDA visual guide showing the five food groups and recommended proportions for healthy eating.'),
(10,'Calorie','A unit of energy; the amount of energy in food that the body uses to perform functions.'),
(10,'Dietary fiber','Indigestible plant material that supports digestive health, lowers cholesterol, and controls blood sugar.'),
(10,'Saturated fat','A type of fat found in animal products that raises LDL (bad) cholesterol when consumed in excess.'),
