(18,'Menopause','The natural biological process marking the end of a woman''s menstrual cycles, typically in the late 40s–50s.'),
(19,'Medicines','Drugs used to treat, prevent, or manage diseases or other medical conditions.'),
(19,'Drugs','Substances other than food that change the structure or function of the body or mind.'),
(19,'Vaccine','A preparation that trains the immune system to recognize and fight a specific disease without causing it.'),
(19,'Side effects','Effects of a medication other than the intended therapeutic effect.'),
