(21,'Psychological dependence','A condition in which a person believes they need alcohol to feel good or function normally.'),
(21,'Physiological dependence','A condition in which the body has a chemical need for alcohol; stopping causes physical withdrawal.'),
(21,'Alcohol use disorder','A chronic brain disease involving compulsive alcohol use despite devastating consequences.'),
(21,'Fetal Alcohol Spectrum Disorders','A range of permanent conditions caused by alcohol exposure during pregnancy — leading preventable cause of intellectual disability.'),
(22,'Substance abuse','The unnecessary or improper use of chemical substances for non-medical purposes.'),
(22,'Illegal drugs','Chemical substances that people of any age may not lawfully manufacture, possess, buy, or sell.'),
(22,'Addiction','A chronic brain disease involving compulsive drug use despite devastating consequences.'),
(22,'Marijuana','A plant whose dried leaves and flowers contain THC; legally variable by state but illegal for minors everywhere.'),
(22,'Inhalants','Substances whose fumes are inhaled to produce intoxication; can cause sudden death even on first use.'),
(22,'Anabolic steroids','Synthetic hormones similar to testosterone; non-medical use is illegal and causes serious health damage.'),
(22,'Hallucinogens','Drugs that alter mood, thoughts, and sensory perceptions, causing hallucinations.'),
(22,'Opiates','Drugs derived from or chemically similar to opium; highly effective pain relievers and highly addictive.'),
(22,'Stimulants','Drugs that speed up central nervous system activity — cocaine, meth, amphetamines.'),
(22,'Rehabilitation','The process of medical and psychological treatment for physiological or psychological dependence on a drug.'),
(22,'Counterfeit pills','Pills made to look exactly like real prescriptions but containing fentanyl or other dangerous substances.'),
